from webhook import WebhookEvent
from scope_checker import should_dispatch_webhook

def test_nominal_topic():
    evt = WebhookEvent("orders::created", "{'id': 1}")
    assert should_dispatch_webhook("orders", evt) is True
    assert should_dispatch_webhook("billing", evt) is False

def test_exact_prefix_match():
    # Test that 'orders' does not match 'orders_admin' topic
    evt = WebhookEvent("orders_admin::created", "{'id': 1}")
    assert should_dispatch_webhook("orders", evt) is False

def test_nested_topic_match():
    # Test that 'orders' matches 'orders::created' but not 'orders_admin::created'
    evt1 = WebhookEvent("orders::created", "{'id': 1}")
    evt2 = WebhookEvent("orders_admin::created", "{'id': 1}")
    assert should_dispatch_webhook("orders", evt1) is True
    assert should_dispatch_webhook("orders", evt2) is False
